package com.lexiscan.document; import com.lexiscan.common.ApiException; import com.lexiscan.user.User; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile; import java.util.*;
@Service public class DocumentService {final DocumentRepository repo;final FileStorage storage; public DocumentService(DocumentRepository r,FileStorage s){repo=r;storage=s;} @Transactional public Document upload(User u,MultipartFile f)throws Exception{var x=storage.save(f);var d=new Document();d.setUser(u);d.setFileName(x.safeName());d.setStoredPath(x.path());d.setFileType(x.type());d.setFileSize(x.size());return repo.save(d);} public Document mine(UUID id,User u){return repo.findById(id).filter(d->d.getUser().getId().equals(u.getId())).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Document not found"));} @Transactional public void delete(UUID id,User u){var d=mine(id,u);storage.delete(d.getStoredPath());repo.delete(d);} }
